export const COUNT=24,HORIZON=40;const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export function create(){return{common:Array(COUNT).fill(true),reaction:.9,sensitivity:1.7,diversity:5,impact:35,initial:50,scenario:'steady'};}
export function validate(s){if(!Array.isArray(s.common)||s.common.length!==COUNT||s.common.some(v=>typeof v!=='boolean'))throw Error('Choose a signal for every participant.');for(const[key,a,b]of[['reaction',.05,1],['sensitivity',.1,3],['diversity',0,30],['impact',0,50],['initial',0,100]])if(!Number.isFinite(s[key])||s[key]<a||s[key]>b)throw Error(`Invalid ${key}.`);if(!['steady','wave','shift'].includes(s.scenario))throw Error('Unknown underlying pattern.');return s;}
export const basePrice=(scenario,t)=>scenario==='wave'?50+12*Math.sin(t/5):scenario==='shift'?(t<14?45:t<27?65:50):50+2*Math.sin(t/4);
export const threshold=(s,i)=>50+s.diversity*((i/(COUNT-1))*2-1);
export function simulate(s){validate(s);let shared=s.initial,privateSignals=Array.from({length:COUNT},(_,i)=>s.initial+8*Math.sin(i*2.4));const history=[];for(let tick=0;tick<HORIZON;tick++){const signals=s.common.map((c,i)=>c?shared:privateSignals[i]),actions=signals.map((signal,i)=>clamp(s.sensitivity*(threshold(s,i)-signal)/20,-1,1)),mean=actions.reduce((a,b)=>a+b,0)/COUNT,base=basePrice(s.scenario,tick),price=base+s.impact*mean;history.push({tick,shared,signals,actions,mean,base,price,error:price-shared});shared+=(price-shared)*s.reaction;privateSignals=privateSignals.map((signal,i)=>signal+.08*(price-signal)+.5*Math.sin(tick*1.7+i));}const oscillation=history.slice(1).reduce((sum,r,i)=>sum+Math.abs(r.price-history[i].price),0)/(HORIZON-1),error=history.reduce((sum,r)=>sum+Math.abs(r.error),0)/HORIZON;return{history,oscillation,error,range:Math.max(...history.map(r=>r.price))-Math.min(...history.map(r=>r.price))};}
